public sealed partial class CityInterface {
 bool OperatingSettled=>S.Get("simulation_tick",0).Long>0;
 string _operatingResidentView="buildings",_operatingResidentSort="population",_operatingHomeChoice="";
 string OperatingProjectIdentity(string id){var p=S["projects"].Get(id,V.Map());var tile=p.Get("tile","").Text;return G.project_name(id)+(S["cells"].Has(tile)?" · "+tile:p.Count==0?" · "+id:"");}
 RectTransform OperatingTableRow(Transform parent,string name,string[] cells,float[] weights=null,bool header=false){
  var row=Row(parent,name,(header?34:46)*TextScale);Height(row,(header?34:46)*TextScale);row.GetComponent<HorizontalLayoutGroup>().spacing=8;row.GetComponent<HorizontalLayoutGroup>().childForceExpandWidth=false;
  for(int i=0;i<cells.Length;i++){if(header&&i==cells.Length-1&&cells[i]==""){OperatingTableActionCell(row);continue;}var label=Label(row,cells[i],header?12:14,header?Muted:Ink,(header?34:46)*TextScale);label.alignment=i==0?TextAnchor.MiddleLeft:TextAnchor.MiddleRight;var size=label.GetComponent<LayoutElement>();size.minWidth=0;size.preferredWidth=0;size.flexibleWidth=weights!=null?weights[i]:1;}
  return row;
 }
 RectTransform OperatingTableActionCell(Transform row){var cell=Row(row,"Table actions",32*TextScale);Height(cell,32*TextScale);Width(cell,128*TextScale);cell.GetComponent<HorizontalLayoutGroup>().spacing=4;return cell;}
 void OperatingTableObjectActions(Transform row,string id){var cell=OperatingTableActionCell(row);if(!S["projects"].Has(id))return;OperatingButton(cell,"检查",()=>Navigate("building",id));OperatingButton(cell,"定位",()=>{SelectBuilding(id);InspectMapFromPage();});}
 void OperatingObjectActions(Transform parent,string id){if(!S["projects"].Has(id))return;var actions=Row(parent,"Source actions "+id,32*TextScale);Height(actions,32*TextScale);OperatingButton(actions,"检查",()=>Navigate("building",id));OperatingButton(actions,"定位",()=>{SelectBuilding(id);InspectMapFromPage();});}
 // fiscal_sources explains the ledger income; replace the attributed portion rather than adding it a second time.
 V OperatingFiscalContributions(V metrics){
  var rows=V.Arr();var attributed=metrics.Get("fiscal_sources",V.Arr());double attributedIncome=0;
  foreach(var item in attributed){var id=item.Get("source_id","").Text;double rate=item.Get("rate",0).Double;attributedIncome+=rate;rows.Add(V.Map("id",id,"label",OperatingProjectIdentity(id)+" · "+item.Get("name","收入").Text,"value",rate));}
  foreach(var item in metrics.Get("fiscal_ledger",V.Arr())){if(item.Get("kind","").Text=="income")continue;var id=item.Get("source_id","").Text;rows.Add(V.Map("id",id,"label",OperatingProjectIdentity(id)+" · "+item.Get("name","维护").Text,"value",-item.Get("rate",0).Double));}
  var remaining=metrics.Get("income",0).Double-attributedIncome;if(Math.Abs(remaining)>.000001)rows.Add(V.Map("id","","label","市政及未归属经营收入","value",remaining));return rows;
 }
 double OperatingHomeCapacity(string id){var p=S["projects"][id];var st=G.project_stats(id);return p.Get("status","").Text=="running"?Math.Max(0,st.Get("housing",0).Double*st.Get("efficiency",1).Double):0;}
 double OperatingHomePeople(string id)=>S["groups"].Values.Where(g=>g.Get("host","").Text==id).Sum(g=>g.Get("count",0).Double);
 double OperatingHomeScore(string id,string key){var groups=S["groups"].Values.Where(g=>g.Get("host","").Text==id).ToArray();double count=groups.Sum(g=>g.Get("count",0).Double);return count>0?groups.Sum(g=>g.Get("count",0).Double*g.Get(key,0).Double)/count:0;}
 string[] OperatingHomes(string filter){
  var homes=S["projects"].Keys.Where(id=>!S["projects"][id].Get("special",false).Bool&&(G.project_stats(id).Get("housing",0).Double>0||OperatingHomePeople(id)>0));
  if(filter!="all"&&!OperatingSettled)return new string[0];
  if(filter!="all")homes=homes.Where(id=>S["groups"].Values.Any(g=>g.Get("host","").Text==id&&ResidentMatchesFilter(g,filter)));
  return (_operatingResidentSort=="vacancy"?homes.OrderByDescending(id=>OperatingHomeCapacity(id)-OperatingHomePeople(id)):_operatingResidentSort=="health"||_operatingResidentSort=="happiness"?homes.OrderBy(id=>OperatingHomeScore(id,_operatingResidentSort)):homes.OrderByDescending(OperatingHomePeople)).ThenBy(id=>id,StringComparer.Ordinal).ToArray();
 }
 void OperatingResidentControls(Transform parent,string filter){
  var views=OperatingGrid(parent,"Resident perspectives");OperatingButton(views,"住宅容量",()=>{_operatingResidentView="buildings";RenderPage();},_operatingResidentView=="buildings");OperatingButton(views,"实际住户组",()=>{_operatingResidentView="groups";RenderPage();},_operatingResidentView=="groups");
  var sorts=OperatingGrid(parent,"Resident sort");foreach(var keyValue in new[]{"population","vacancy","health","happiness"}){var key=keyValue;OperatingButton(sorts,V.Map("population","人口 ↓","vacancy","空房 ↓","health","健康 ↑","happiness","幸福 ↑")[key].Text,()=>{_operatingResidentSort=key;RenderPage();},_operatingResidentSort==key);}
  if(!OperatingSettled)Label(parent,"就业、口粮和服务分配待首次实际结算；空住宅也列入容量视图。",13,Muted);
 }
