 }
 string[] SortOperatingGroups(string[] ids)=> (_operatingResidentSort=="health"||_operatingResidentSort=="happiness"?ids.OrderBy(id=>S["groups"][id].Get(_operatingResidentSort,0).Double):_operatingResidentSort=="vacancy"?ids.OrderByDescending(id=>S["groups"][id]["host"].Text=="homeless"?0:OperatingHomeCapacity(S["groups"][id]["host"].Text)-OperatingHomePeople(S["groups"][id]["host"].Text)):ids.OrderByDescending(id=>S["groups"][id].Get("count",0).Double)).ThenBy(id=>id,StringComparer.Ordinal).ToArray();
