  var tabs=OperatingGrid(_body,"Resource table selector");foreach(var keyValue in options){var key=keyValue;OperatingButton(tabs,key=="energy"?"电力":Resource(key),()=>Navigate("resources",key),key==resource);}if(!settled)OperatingStateNote();
