    foreach(var idValue in receipts.Select(x=>x.Get("source_id","").Text).Union(expenses.Select(x=>x.Get("source_id","").Text))){var id=idValue;var attributed=receipts.Where(x=>x.Get("source_id","").Text==id);double tax=attributed.Where(x=>x.Get("aggregate","").Text=="tax").Sum(x=>x.Get("rate",0).Double);double land=attributed.Where(x=>x.Get("aggregate","").Text=="land_rent").Sum(x=>x.Get("rate",0).Double);double pollution=attributed.Where(x=>x.Get("aggregate","").Text=="pollution_fee").Sum(x=>x.Get("rate",0).Double);double expense=expenses.Where(x=>x.Get("source_id","").Text==id).Sum(x=>x.Get("rate",0).Double);var row=OperatingTableRow(table,"Fiscal building "+id,new[]{OperatingProjectIdentity(id),Signed(tax),Signed(land),Signed(pollution),F(expense),Signed(tax+land+pollution-expense)},new[]{2.5f,1,1,1,1,1.1f});OperatingTableObjectActions(row,id);}
