 string OperatingPolicySlotName(string slot)=>V.Map("Tax","税收","Labor","用工","Environment","环境","Procurement","采购","Land","土地").Get(slot,slot).Text;
 V OperatingPolicyMetricRows(V baseline,V proposal){
  var a=baseline.Get("metrics",V.Map());var b=proposal.Get("metrics",V.Map());var rows=V.Arr();Action<string,double,double> add=(title,before,after)=>rows.Add(V.Map("title",title,"before",before,"after",after));
  add("经营净额 /月",a.Get("cashflow",0).Double,b.Get("cashflow",0).Double);
  foreach(var resource in new[]{"food","material","goods"}){add(Resource(resource)+"净流 /月",a.Get("flows",V.Map()).Get(resource,0).Double,b.Get("flows",V.Map()).Get(resource,0).Double);add(Resource(resource)+"实际消耗 /月",OperatingPolicyInputs(a,resource),OperatingPolicyInputs(b,resource));}
  add("电力供给 · 能力",a.Get("energy",0).Double,b.Get("energy",0).Double);add("电力需求 · 能力",a.Get("energy_need",0).Double,b.Get("energy_need",0).Double);
  foreach(var kind in new[]{"medical","education","entertainment","commercial"}){double before=a.Get("service_links",V.Arr()).Where(x=>x.Get("kind","").Text==kind).Sum(x=>x.Get("people",0).Double);double after=b.Get("service_links",V.Arr()).Where(x=>x.Get("kind","").Text==kind).Sum(x=>x.Get("people",0).Double);add(Service(kind)+"实际覆盖 · 人",before,after);}return rows;
 }
 void OperatingPolicyMetrics(Transform parent,V baseline,V proposal,bool compact=false){
  var rows=OperatingPolicyMetricRows(baseline,proposal);var visible=compact?rows.Where(row=>Math.Abs(row["after"].Double-row["before"].Double)>.000001).ToArray():rows.ToArray();
  OperatingTableRow(parent,"Policy comparison headings",new[]{"同一步下一结算","不更换","采用后","变化"},new[]{1.8f,1,1,1},true);foreach(var row in visible)OperatingPolicyMetricRow(parent,row["title"].Text,row["before"].Double,row["after"].Double);
  if(compact){if(visible.Length==0)Label(parent,"该候选在当前城市下一步结算中没有数值变化；政策规则与实施费用仍有效。",13,Muted);var unchanged=rows.Where(row=>Math.Abs(row["after"].Double-row["before"].Double)<=.000001).ToArray();if(unchanged.Length>0)Fold(parent,"未变化指标 · "+unchanged.Length+" 项",details=>{foreach(var row in unchanged)OperatingPolicyMetricRow(details,row["title"].Text,row["before"].Double,row["after"].Double);});}
  Label(parent,"两列来自同一步真实结算预测；实施费只在应用时一次支付，不加入经营月率。",13,Muted);
 }
 double OperatingPolicyInputs(V metrics,string resource)=>metrics.Get("activity_ledger",V.Map()).Values.Sum(entries=>entries.Where(x=>x.Get("resource","").Text==resource&&x.Get("kind","").Text=="input").Sum(x=>x.Get("rate",0).Double));
 void OperatingPolicyMetricRow(Transform parent,string title,double before,double after){var row=OperatingTableRow(parent,"Policy effect "+title,new[]{title,F(before),F(after),Signed(after-before)},new[]{1.8f,1,1,1});var delta=row.GetComponentsInChildren<Text>().Last();delta.color=Math.Abs(after-before)>.000001?Ink:Muted;}
 void OperatingPoliciesPage(){
  if(_advancedWorkspace){PoliciesPage();return;}var selector=OperatingSection(_body,"经营政策","通货 "+F(S.Get("currency",0).Double));var slots=OperatingGrid(selector,"Compact policy categories");foreach(var keyValue in new[]{"Tax","Labor","Environment","Procurement","Land"}){var key=keyValue;OperatingButton(slots,OperatingPolicySlotName(key),()=>{_policySlot=key;_policyChoice="";if(_comparisonValid)ClearComparison();RenderPage();},_policySlot==key);}
  string currentId=S["block"]["policies"].Get(_policySlot,"").Text;var current=G.c.policies.Get(currentId,V.Map());var ids=G.c.policies.Keys.Where(id=>G.c.policies[id]["slot"].Text==_policySlot).ToArray();if(!ids.Contains(_policyChoice))_policyChoice=ids.FirstOrDefault(id=>id!=currentId)??currentId;
  Label(selector,"当前 · "+current.Get("name","本槽未采用政策").Text,17,Green);Label(selector,current.Get("summary","").Text,13,Muted);foreach(var idValue in ids){var id=idValue;OperatingButton(selector,(_policyChoice==id?"● ":"")+G.c.policies[id]["name"].Text+(id==currentId?" · 当前":""),()=>{_policyChoice=id;if(_comparisonValid)ClearComparison();RenderPage();},_policyChoice==id);}
  if(_policyChoice=="")return;var policy=G.c.policies[_policyChoice];var baseline=_planner.snapshot(G);var preview=_planner.policy(G,_policyChoice);var compare=OperatingSection(_body,"候选 · "+policy["name"].Text);Label(compare,policy.Get("summary","").Text,14,Muted);if(preview.Get("ok",false).Bool)OperatingPolicyMetrics(compare,baseline,preview["map_snapshot"],true);else Label(compare,preview.Get("error","预测不可用").Text,14,Gold);
  var selected=_policyChoice;var version=_planner.version(G);double price=G.c.balance["policy_switch_price"].Double;bool isCurrent=currentId==selected;Label(compare,isCurrent?"已采用，无更换费用":"更换即付 "+F(price)+" 通货 · 支付后 "+F(S.Get("currency",0).Double-price),14,Gold);
  WorkspaceActions(isCurrent?"「"+policy["name"].Text+"」已采用":"实施「"+policy["name"].Text+"」 · 付 "+F(price,0)+"通货 · 余 "+F(S.Get("currency",0).Double-price,0),()=>{if(version!=_planner.version(G)){RenderPage();ShowMessage("城市已变化，请核对刷新后的预测。");return;}Command(g=>g.switch_policy(selected));},isCurrent||!preview.Get("ok",false).Bool||S.Get("currency",0).Double<price);OperatingButton(_body,"完整政策、地图预测与规则 →",()=>OpenAdvancedWorkspace("policies"),true);
 }
